"""Minimal, standard-library client for OpenAI's Responses API.

Set ``OPENAI_API_KEY`` before use.  This module deliberately does not log
requests or response bodies, so private prompt text is not written to stdout
or exception messages by the client.
"""

from __future__ import annotations

import json
import os
import socket
from typing import Any, Mapping
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


DEFAULT_ENDPOINT = "https://api.openai.com/v1/responses"


class OpenAIClientError(RuntimeError):
    """Base error raised by this module (with no prompt or body attached)."""


class OpenAIHTTPError(OpenAIClientError):
    """An API request received a non-success HTTP status."""

    def __init__(self, status: int) -> None:
        self.status = status
        super().__init__(f"OpenAI API request failed with HTTP status {status}.")


def create_response(
    prompt: str,
    model: str,
    *,
    instructions: str | None = None,
    max_output_tokens: int | None = None,
    timeout: float = 60.0,
    api_key: str | None = None,
    endpoint: str = DEFAULT_ENDPOINT,
) -> dict[str, Any]:
    """Send *prompt* to the Responses API and return its decoded JSON object.

    The API key defaults to ``OPENAI_API_KEY``.  Pass an explicit key only
    when necessary; avoid committing it or including it in source code.

    ``endpoint`` is injectable primarily for tests or a compatible gateway.
    Only HTTPS endpoints are accepted to protect the API key and prompt.
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    if not endpoint.startswith("https://"):
        raise ValueError("endpoint must use HTTPS")

    secret = api_key or os.environ.get("OPENAI_API_KEY")
    if not secret:
        raise OpenAIClientError("OPENAI_API_KEY is not set.")

    payload: dict[str, Any] = {"model": model, "input": prompt}
    if instructions is not None:
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        if max_output_tokens <= 0:
            raise ValueError("max_output_tokens must be positive")
        payload["max_output_tokens"] = max_output_tokens

    request = Request(
        endpoint,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {secret}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        # Do not include the API's response body: it can contain user content.
        raise OpenAIHTTPError(exc.code) from None
    except (URLError, socket.timeout, TimeoutError) as exc:
        raise OpenAIClientError("Could not reach the OpenAI API.") from exc
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIClientError("OpenAI returned an invalid JSON response.") from exc


def response_text(response: Mapping[str, Any]) -> str:
    """Return concatenated text from a Responses API response.

    This supports both the convenient ``output_text`` field and the canonical
    ``output``/``content`` structure returned by the API.
    """
    output_text = response.get("output_text")
    if isinstance(output_text, str):
        return output_text

    parts: list[str] = []
    output = response.get("output", [])
    if not isinstance(output, list):
        return ""
    for item in output:
        if not isinstance(item, Mapping):
            continue
        content = item.get("content", [])
        if not isinstance(content, list):
            continue
        for block in content:
            if isinstance(block, Mapping) and block.get("type") == "output_text":
                text = block.get("text")
                if isinstance(text, str):
                    parts.append(text)
    return "".join(parts)


__all__ = [
    "DEFAULT_ENDPOINT",
    "OpenAIClientError",
    "OpenAIHTTPError",
    "create_response",
    "response_text",
]
